def transform(grid):
    h, w = len(grid), len(grid[0])
    marker = next((v for row in grid for v in row if v not in (0, 9)), None)
    if marker is None:
        return [row[:] for row in grid]
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == marker]
    r0, r1 = min(r for r,c in pts), max(r for r,c in pts)
    c0, c1 = min(c for r,c in pts), max(c for r,c in pts)
    shape = [(r-r0, c-c0) for r,c in pts]
    out = [row[:] for row in grid]
    matches = []
    for dr in range(h-(r1-r0+1)+1):
        for dc in range(w-(c1-c0+1)+1):
            if all(grid[dr+sr][dc+sc] == 0 for sr,sc in shape):
                matches.append((dr,dc))
    for dr,dc in matches:
        for sr,sc in shape:
            out[dr+sr][dc+sc] = marker
    return out
